def price_with(kind, price):
    if kind == "none":
        return price
    if kind == "percent10":
        return price * 9 // 10
    raise ValueError("неизвестная скидка")

DISCOUNTS = {
    "none": lambda price: price,
    "percent10": lambda price: price * 9 // 10,
    "minus50": lambda price: max(0, price - 50),
}


def price_with(kind, price):
    if kind not in DISCOUNTS:
        raise ValueError("неизвестная скидка")
    return DISCOUNTS[kind](price)

handlers = {}


def subscribe(event, handler):
    handlers.setdefault(event, []).append(handler)


def publish(event, payload):
    for handler in handlers.get(event, []):
        handler(payload)

class Bird:
    def fly(self):
        return "летит"


class Penguin(Bird):
    def fly(self):
        raise NotImplementedError("пингвины не летают")

for bird in [Bird(), Penguin()]:
    try:
        print(bird.fly())
    except NotImplementedError as e:
        print("сломалось:", e)
